import java.nio.charset.StandardCharsets;
import io.netty.channel.Channel;
import io.netty.buffer.ByteBuf;
import io.netty.buffer.Unpooled;

public class Gt06ProtocolDecoderTest {

    @Test
    public void decodeGpsTestNotNullBuf() {
        Position position = new Position();
        ByteBuf buf = Unpooled.copiedBuffer("test", StandardCharsets.UTF_8);
        boolean result = Gt06ProtocolDecoder.decodeGps(position, buf, true, TimeZone.getDefault());

        Assert.assertEquals(true, result);
    }

    @Test(expected = NullPointerException.class)
    public void decodeGpsTestNullBuf() {
        Position position = new Position();
        Gt06ProtocolDecoder.decodeGps(position, null, true, TimeZone.getDefault());
    }

    @Test
    public void decodeGpsWithParametersTest() {
        Position position = new Position();
        ByteBuf buf = Unpooled.copiedBuffer("test", StandardCharsets.UTF_8);
        boolean result = Gt06ProtocolDecoder.decodeGps(position, buf, true, true, true, TimeZone.getDefault());

        Assert.assertEquals(true, result);
    }

    @Test(expected = NullPointerException.class)
    public void decodeGpsWithParametersNullBufTest() {
        Position position = new Position();
        Gt06ProtocolDecoder.decodeGps(position, null, true, true, true, TimeZone.getDefault());
    }

    @Test
    public void decodeTest() throws Exception {
        Position position = new Position();
        ByteBuf buf = Unpooled.copiedBuffer("test", StandardCharsets.UTF_8);
        Channel channel = Mockito.mock(Channel.class);
        SocketAddress address = Mockito.mock(SocketAddress.class);
        Gt06ProtocolDecoder decoder = Mockito.spy(new Gt06ProtocolDecoder(Mockito.mock(Protocol.class)));

        Object result = decoder.decode(channel, address, buf.toString(StandardCharsets.UTF_8));

        Assert.assertTrue(result instanceof Position);
    }

